                for line in content.split("\n"):
                    if line.startswith("URL:"):
                        url = line.replace("URL:", "").strip()
                        if url:
                            successfully_fetched.add(url)
            elif "[FETCH STATUS: FAILED]" in content:
                for line in content.split("\n"):
                    if line.startswith("URL:"):
                        url = line.replace("URL:", "").strip()
                        if url:
                            failed_fetched.add(url)
            elif "URL:" in content or "http" in content:
                for line in content.split("\n"):
                    if line.startswith("URL:"):
                        url = line.replace("URL:", "").strip()
